        private class KrakenTentacleStateMachine : EntityStateMachine
        {
            public KrakenTentacleStateMachine()
            {
                AddState(new HiddenState());
                AddState(new IdleState());
                AddState(new AppearState());
                AddState(new WeaponState());
                AddState(new SmashState());
                AddState(new DisappearState());
