        public static int EvaluateNextAction(Entity entity, int currentAction)
        {
            using var weightsItem = ListPool<float>.Rent();
            var weights = weightsItem.Value;

            using var checkTilesItem = ListPool<LawnGrid>.Rent();
            var checkTiles = checkTilesItem.Value;

            float weightSum = 0;
            for (int i = 0; i < actionPool.Length; i++)
            {
                var action = actionPool[i];
                if (currentAction != action)
                {
                    var weight = actionWeights[i];
                    checkTiles.Clear();
                    GetPossibleActionTiles(entity, action, checkTiles);
                    if (checkTiles.Count > 0)
                    {
                        weights.Add(weight);
                        weightSum += weight;
                        continue;
                    }
                }
                weights.Add(0);
            }
            if (weightSum <= 0)
                return currentAction;
            return actionPool.WeightedRandom(weights, entity.RNG);
        }
        public static void GetPossibleActionTiles(Entity entity, int action, List<LawnGrid> results)
        {
            switch (action)
            {
                case ACTION_GATLIN:
                    GetPossibleUseGatlinTiles(entity, results);
                    break;
                case ACTION_CANNON:
                    GetPossibleUseCannonTiles(entity, results);
                    break;
                case ACTION_LASER:
                    GetPossibleUseLaserTiles(entity, results);
                    break;
                case ACTION_SUMMON:
                    GetPossibleUseSummonTiles(entity, results);
                    break;
                case ACTION_SMASH:
                    GetPossibleUseSmashTiles(entity, results);
                    break;
            }
        }
        public static void SetInactive(Entity entity, bool value)
        {
            if (value)
            {
                if (!entity.HasBuff<KrakenTentacleInactiveBuff>())
                    entity.AddBuff<KrakenTentacleInactiveBuff>();
            }
            else
            {
                entity.RemoveBuffs<KrakenTentacleInactiveBuff>();
            }
        }
        public static bool IsTileTakenByKrakenTentacle(LevelEngine level, int column, int lane)
        {
            krakenTentaclePredicator.SetTile(column, lane);
            return level.EntityExists(krakenTentaclePredicator);
        }
        public static bool IsTileTakenByKraken(LevelEngine level, int column, int lane)
        {
            krakenPredicator.SetTile(column, lane);
            return level.EntityExists(krakenPredicator);
        }
        public static bool CanAppearAtTile(Entity entity, int column, int lane)
        {
            if (!entity.Level.IsWaterGrid(column, lane))
                return false;
            if (IsTileTakenByKrakenTentacle(entity.Level, column, lane))
            {
                return false;
            }
            if (IsTileTakenByKraken(entity.Level, column, lane))
            {
                return false;
            }
            return true;
        }
        #region 攻击动作判定（加特林）
        public static void GetPossibleUseGatlinTiles(Entity entity, List<LawnGrid> results)
        {
            var level = entity.Level;
            int maxColumn = entity.Level.GetMaxColumnCount();
            var maxLane = entity.Level.GetMaxLaneCount();
            for (int lane = 0; lane < maxLane; lane++)
            {
                for (int x = 0; x < maxColumn; x++)
                {
                    int column = entity.GetMirroredColumn(x, false);
                    if (!CanAppearAtTile(entity, column, lane))
                        continue;
                    if (CanUseGatlinAtTile(entity, column, lane))
                    {
                        var grid = level.GetGrid(column, lane);
                        if (grid != null)
                        {
                            results.Add(grid);
                        }
                    }
                }
            }
        }
        public static bool CanUseGatlinAtTile(Entity entity, int column, int lane)
        {
            DetectionParams detectParams = new DetectionParams(entity, entity.GetFaction(), gatlinDetector.GetDetectionBoundsAtTile(entity, column, lane));
            return gatlinDetector.DetectExists(detectParams);
        }
        public static bool CanUseGatlin(Entity entity)
        {
            return gatlinDetector.DetectExists(entity);
        }
        #endregion

