        #region 隐藏
        private class HiddenState : EntityStateMachineState
        {
            public HiddenState() : base(STATE_HIDDEN, ANIMATION_STATE_HIDDEN) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(3f);
                SetShadowAlpha(entity, 0);
                SetInactive(entity, true);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                if (IsAutoAct(entity))
                {
                    var stateTimer = stateMachine.GetStateTimer(entity);
                    stateTimer.Run(stateMachine.GetSpeed(entity));
                    if (stateTimer.Expired)
                    {
                        stateTimer.Reset();
                        NextAppear(entity);
                    }
                }
            }
        }
        #endregion

        #region 出现
        public static LawnGrid SelectTileToAppear(Entity entity, List<LawnGrid> tiles)
        {
            return tiles.GetRandomOfTopOnes(g => GetSelectTilePriorityToAppear(entity, g), entity.RNG, false);
        }
        public static float GetSelectTilePriorityToAppear(Entity entity, LawnGrid tile)
        {
            if (tile.IsEmpty())
                return 1;
            if (tile.HasEntity(e => entity.IsFriendly(e) || e.StunsKrakenWhenThrown()))
                return -1;
            return 0;
        }
        public static void NextAppear(Entity entity)
        {
            int current = GetNextAction(entity);

            using var resultTilesItem = ListPool<LawnGrid>.Rent();
            var resultTiles = resultTilesItem.Value;
            var next = EvaluateNextAction(entity, current);

            GetPossibleActionTiles(entity, next, resultTiles);

            SetNextAction(entity, next);

            if (resultTiles.Count > 0)
            {
                var chosenTile = SelectTileToAppear(entity, resultTiles);
                entity.Position = chosenTile.GetEntityPosition();
            }
            stateMachine.StartState(entity, STATE_APPEAR);
        }
        public static void DestroyContraptionsInTile(Entity entity)
        {
            var grid = entity.GetGrid();
            if (grid == null)
                return;
            DestroyContraptionsInTile(entity, grid);
        }
        public static void DestroyContraptionsInTile(Entity entity, LawnGrid tile)
        {
            var damageEffects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);
            using var gridEntities = tile.GetEntitiesDisposeable();
            foreach (var ent in gridEntities.Value)
            {
                ent.Die(damageEffects, entity);
            }
        }
        public static void DealDrillDamage(Entity entity)
        {
            using var collidersItem = ListPool<IEntityCollider>.Rent();
            var colliders = collidersItem.Value;
            drillDetector.DetectMultiple(entity, colliders);
            var effects = new DamageEffectList(VanillaDamageEffects.SLICE);
            foreach (var collider in colliders)
            {
                collider.TakeDamage(entity.GetDamage() * DRILL_DAMAGE_MULTIPLIER, effects, entity);
            }
        }
        private class AppearState : EntityStateMachineState
        {
            public AppearState() : base(STATE_APPEAR, ANIMATION_STATE_APPEAR) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(1);
                SetInactive(entity, false);
                if (entity.IsOnWater())
                {
                    entity.PlaySplashEffect();
                    entity.PlaySound(VanillaSoundID.splashBig);
                }
                DestroyContraptionsInTile(entity);
                DealDrillDamage(entity);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.Run(stateMachine.GetSpeed(entity));
                SetShadowAlpha(entity, stateTimer.GetPassedPercentage());
                if (stateTimer.Expired)
                {
                    stateTimer.Reset();
                    stateMachine.StartState(entity, STATE_IDLE);
                }
            }
        }
        #endregion

        #region 消失
        private class DisappearState : EntityStateMachineState
        {
            public DisappearState() : base(STATE_DISAPPEAR, ANIMATION_STATE_DISAPPEAR) { }
            public override int GetAnimationSubstate(int substate)
            {
                switch (substate)
                {
                    case SUBSTATE_RECALLED:
                        return ANIMATION_SUBSTATE_RECALLED;
                }
                return ANIMATION_SUBSTATE_DRILL;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(1);
                if (entity.IsOnWater())
                {
                    entity.PlaySplashEffect();
                    entity.PlaySound(VanillaSoundID.splashBig);
                }
                SetInactive(entity, true);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.Run(stateMachine.GetSpeed(entity));
                SetShadowAlpha(entity, stateTimer.GetTimeoutPercentage());
                if (stateTimer.Expired)
                {
                    stateTimer.Reset();
                    stateMachine.StartState(entity, STATE_HIDDEN);
                }
            }
            public const int SUBSTATE_DRILL = 0;
            public const int SUBSTATE_RECALLED = 1;
            public const int ANIMATION_SUBSTATE_DRILL = 0;
            public const int ANIMATION_SUBSTATE_RECALLED = 1;
        }
        #endregion

        #region 待命
        private class IdleState : EntityStateMachineState
        {
            public IdleState() : base(STATE_IDLE, ANIMATION_STATE_IDLE) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(3f);
                SetShadowAlpha(entity, 1);
                SetInactive(entity, false);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.Run(stateMachine.GetSpeed(entity));
                if (stateTimer.Expired)
                {
                    stateTimer.Reset();

                    var nextAction = GetNextAction(entity);
                    bool success = false;
                    switch (nextAction)
                    {
                        case ACTION_GATLIN:
                            if (CanUseGatlin(entity))
                            {
                                stateMachine.StartState(entity, STATE_WEAPON);
                                success = true;
                            }
                            break;
                        case ACTION_CANNON:
                            if (CanUseCannon(entity))
                            {
                                stateMachine.StartState(entity, STATE_WEAPON);
                                success = true;
                            }
                            break;
                        case ACTION_LASER:
                            if (CanUseLaser(entity))
                            {
                                stateMachine.StartState(entity, STATE_WEAPON);
                                success = true;
                            }
                            break;
                        case ACTION_SUMMON:
                            if (CanUseSummon(entity))
                            {
                                stateMachine.StartState(entity, STATE_WEAPON);
                                success = true;
                            }
                            break;
                        case ACTION_SMASH:
                            if (CanUseSmash(entity))
                            {
                                stateMachine.StartState(entity, STATE_SMASH);
                                success = true;
                            }
                            break;
                    }
                    if (!success)
                    {
                        stateMachine.StartState(entity, STATE_DISAPPEAR);
                    }
                }
            }
        }
        #endregion

        #region 武器
        public static Vector3 GetGatlinBulletPosition(Entity entity)
        {
            var offset = GATLIN_PROJECTILE_OFFSET;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static Vector3 GetCannonMissilePosition(Entity entity)
        {
            var offset = CANNON_MISSILE_OFFSET;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static Vector3 GetLaserPosition(Entity entity)
        {
            var offset = LASER_OFFSET;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        public static Vector3 GetSummonPosition(Entity entity)
        {
            var offset = SUMMON_OFFSET;
            offset.x *= entity.GetFacingX();
            return entity.Position + offset;
        }
        private class WeaponState : EntityStateMachineState
        {
            public WeaponState() : base(STATE_WEAPON, ANIMATION_STATE_WEAPON) { }
            public override int GetAnimationSubstate(int substate)
            {
                return substate;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.ResetSeconds(1f);

                entity.PlaySound(VanillaSoundID.krakenHatchOpen);
            }
            public override void OnExit(EntityStateMachine machine, Entity entity)
            {
                base.OnExit(machine, entity);
                entity.SetAnimationBool("GatlinFiring", false);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.Run(stateMachine.GetSpeed(entity));
                var substate = stateMachine.GetSubState(entity);
                switch (substate)
                {
                    case SUBSTATE_OPEN:
                        var action = GetNextAction(entity);
                        switch (action)
                        {
                            case ACTION_GATLIN:
                                entity.SetModelProperty("Weapon", WEAPON_GATLIN);
                                if (substateTimer.Expired)
                                {
                                    stateMachine.StartSubState(entity, SUBSTATE_GATLIN);
                                    substateTimer.ResetSeconds(3f);
                                }
                                break;
                            case ACTION_CANNON:
                                entity.SetModelProperty("Weapon", WEAPON_CANNON);
                                if (substateTimer.Expired)
                                {
                                    CannonFire(entity);
                                    stateMachine.StartSubState(entity, SUBSTATE_CANNON);
                                    substateTimer.ResetSeconds(1f);
                                }
                                break;
                            case ACTION_LASER:
                                entity.SetModelProperty("Weapon", WEAPON_LASER);
                                if (substateTimer.Expired)
                                {
                                    LaserFire(entity);
                                    stateMachine.StartSubState(entity, SUBSTATE_LASER);
                                    substateTimer.ResetSeconds(1f);
                                }
                                break;
                            case ACTION_SUMMON:
                                entity.SetModelProperty("Weapon", WEAPON_SUMMON);
                                if (substateTimer.Expired)
                                {
                                    SummonZombie(entity);
                                    stateMachine.StartSubState(entity, SUBSTATE_SUMMON);
                                    substateTimer.ResetSeconds(1f);
                                }
                                break;
                        }
                        break;
                    case SUBSTATE_CLOSE:
                        if (substateTimer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_DISAPPEAR);
                        }
                        break;
                    case SUBSTATE_GATLIN:
                        for (int i = 0; i < substateTimer.PassedIntervalCount(GATLIN_INTERVAL); i++)
                        {
                            var angleOffset = entity.RNG.Next(-GATLIN_ANGLE_OFFSET, GATLIN_ANGLE_OFFSET);
                            var direction = entity.GetFacingDirection().RotateClockwiseXZ(angleOffset);
                            var args = entity.GetShootParams();
                            args.projectileID = VanillaProjectileID.bullet;
                            args.velocity = direction * GATLIN_BULLET_SPEED;
                            args.position = GetGatlinBulletPosition(entity);
                            args.damage = entity.GetDamage() * GATLIN_DAMAGE_MULTIPLIER;
                            entity.ShootProjectile(args);
                            entity.PlaySound(VanillaSoundID.gunShot, volume: 0.5f);
                            entity.SetAnimationBool("GatlinFiring", true);
                        }
                        if (substateTimer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_CLOSE);
                            entity.PlaySound(VanillaSoundID.krakenHatchClose);
                            substateTimer.ResetSeconds(0.5f);
                            entity.SetAnimationBool("GatlinFiring", false);
                        }
                        break;
                    case SUBSTATE_CANNON:
                    case SUBSTATE_LASER:
                    case SUBSTATE_SUMMON:
                        if (substateTimer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_CLOSE);
                            entity.PlaySound(VanillaSoundID.krakenHatchClose);
                            substateTimer.ResetSeconds(0.5f);
                        }
                        break;
                }
            }
            public static void CannonFire(Entity entity)
            {
                var args = entity.GetShootParams();
                args.spawnParam.SetProperty(VanillaEntityProps.RANGE, CANNON_MISSILE_EXPLODE_RADIUS);
                args.projectileID = VanillaProjectileID.missile;
                args.velocity = entity.GetFacingDirection() * CANNON_MISSILE_SPEED;
                args.position = GetCannonMissilePosition(entity);
                args.damage = entity.GetDamage() * CANNON_MISSILE_DAMAGE_MULTIPLIER;
                entity.ShootProjectile(args);
                entity.PlaySound(VanillaSoundID.missile);
            }
            public static void LaserFire(Entity entity)
            {
                var sourcePosition = GetLaserPosition(entity);
                var param = entity.GetSpawnParams();
                param.SetProperty(VanillaEntityProps.DAMAGE, entity.GetDamage() * LASER_DAMAGE_MULTIPLIER);
                param.SetProperty(EngineEntityProps.FLIP_X, entity.IsFacingLeft());
                param.SetProperty(LogicEntityProps.HSV_OFFSET, new Vector3(-30, 0, 0));

                entity.Spawn(VanillaEffectID.amethystPylonLaser, sourcePosition, param);
                entity.PlaySound(VanillaSoundID.scifiLaser);
            }
            public static void SummonZombie(Entity entity)
            {
                var sourcePosition = GetSummonPosition(entity);
                var param = entity.GetSpawnParams();
                entity.Spawn(VanillaEnemyID.ironHelmettedZombie, sourcePosition, param);
            }
            public const int SUBSTATE_OPEN = 0;
            public const int SUBSTATE_CLOSE = 1;
            public const int SUBSTATE_GATLIN = 2;
            public const int SUBSTATE_CANNON = 3;
            public const int SUBSTATE_LASER = 4;
            public const int SUBSTATE_SUMMON = 5;
            public const int GATLIN_INTERVAL = 1;
        }
        #endregion

        #region 砸击
        private class SmashState : EntityStateMachineState
        {
            public SmashState() : base(STATE_SMASH, ANIMATION_STATE_SMASH) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.ResetSeconds(2 / 3f);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var substateTimer = stateMachine.GetSubStateTimer(entity);
                substateTimer.Run(stateMachine.GetSpeed(entity));
                var substate = stateMachine.GetSubState(entity);
                switch (substate)
                {
                    case SUBSTATE_SWING:
                        if (substateTimer.Expired)
                        {
                            stateMachine.StartSubState(entity, SUBSTATE_SMASHED);
                            substateTimer.ResetSeconds(1 / 12f);
                            Smash(entity);
                            SetInactive(entity, true);
                        }
                        break;
                    case SUBSTATE_SMASHED:
                        SetShadowAlpha(entity, substateTimer.GetTimeoutPercentage());
                        if (substateTimer.Expired)
                        {
                            stateMachine.StartState(entity, STATE_HIDDEN);
                        }
                        break;
                }
            }
            public void Smash(Entity entity)
            {
                var point = entity.Position + entity.GetFacingDirection() * (SMASH_RANGE * 0.5f);
                if (entity.Level.IsWaterAt(point.x, point.z))
                {
                    entity.PlaySplashEffectAt(point);
                    entity.PlaySound(VanillaSoundID.splashBig);
                }
                else if (entity.Level.IsLandAt(point.x, point.z))
                {
                    entity.PlaySound(VanillaSoundID.anvil);
                    entity.Level.ShakeScreen(10, 0, 15);
                }

                using var collidersItem = ListPool<IEntityCollider>.Rent();
                var colliders = collidersItem.Value;
                smashDetector.DetectMultiple(entity, colliders);

                var smashEffects = new DamageEffectList(VanillaDamageEffects.IMPACT, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN);
                var instakillEffects = new DamageEffectList(VanillaDamageEffects.INSTA_KILL);

                foreach (var collider in colliders)
                {
                    if (collider.Entity.Type == EntityTypes.PLANT || collider.Entity.Type == EntityTypes.OBSTACLE)
                    {
                        if (collider.IsForMain())
                        {
                            collider.Entity.Die(instakillEffects, entity);
                            collider.Entity.PlaySound(VanillaSoundID.smash);
                        }
                    }
                    else
                    {
                        collider.TakeDamage(entity.GetDamage() * SMASH_DAMAGE_MULTIPLIER, smashEffects, entity);
                        collider.Entity.PlaySound(VanillaSoundID.punch);
                    }
                }
            }
            public const int SUBSTATE_SWING = 0;
            public const int SUBSTATE_SMASHED = 1;
        }
        #endregion

        #region 钻击

        private class DrillState : EntityStateMachineState
        {
            public DrillState() : base(STATE_DRILL, ANIMATION_STATE_DRILL) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var timer = stateMachine.GetStateTimer(entity);
                timer.ResetSeconds(0.5f);
                SetInactive(entity, false);
                if (entity.IsOnWater())
                {
                    entity.PlaySplashEffect();
                    entity.PlaySound(VanillaSoundID.splashBig);
                }
                DestroyContraptionsInTile(entity);
                DealDrillDamage(entity);
            }
            public override void OnUpdateAI(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateAI(stateMachine, entity);
                var timer = stateMachine.GetStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));

                float alpha = timer.GetPassedPercentage();
                if (alpha > 0.5f)
                {
                    alpha = 1 - alpha;
                }
                SetShadowAlpha(entity, alpha);
                if (timer.Expired)
                {
                    if (entity.IsOnWater())
                    {
                        entity.PlaySplashEffect();
                        entity.PlaySound(VanillaSoundID.splashBig);
                    }
                    stateMachine.StartState(entity, STATE_HIDDEN);
                }
            }
        }
        #endregion

        #region 眩晕
        public static void Stun(Entity chest, float seconds)
        {
            stateMachine.StartState(chest, STATE_STUNNED);
            var timer = stateMachine.GetStateTimer(chest);
            timer.ResetSeconds(seconds);
        }
        private class StunnedState : EntityStateMachineState
        {
            public StunnedState() : base(STATE_STUNNED, ANIMATION_STATE_STUNNED) { }
            public override int GetAnimationSubstate(int substate)
            {
                return substate;
            }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var stateTimer = stateMachine.GetStateTimer(entity);
                stateTimer.ResetSeconds(10f);
            }
            public override void OnUpdateLogic(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateLogic(stateMachine, entity);
                var substate = stateMachine.GetSubState(entity);
                var timer = stateMachine.GetStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                if (timer.Expired)
                {
                    stateMachine.StartState(entity, STATE_DISAPPEAR);
                }
            }
        }
        #endregion

        #region 死亡
        private class DeathState : EntityStateMachineState
        {
            public DeathState() : base(STATE_DEATH, ANIMATION_STATE_DEATH) { }
            public override void OnEnter(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnEnter(stateMachine, entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.ResetSeconds(1f);
                SetInactive(entity, false);
                SetShadowAlpha(entity, 1);
            }
            public override void OnUpdateLogic(EntityStateMachine stateMachine, Entity entity)
            {
                base.OnUpdateLogic(stateMachine, entity);
                var substate = stateMachine.GetSubState(entity);
                var timer = stateMachine.GetSubStateTimer(entity);
                timer.Run(stateMachine.GetSpeed(entity));
                if (timer.Expired)
                {
                    entity.Remove();
                    Explosion.Spawn(entity, entity.GetCenter(), 120);
                    entity.PlaySound(VanillaSoundID.largeExplosion);
                    entity.Level.ShakeScreen(10, 0, 15);
                }
            }
        }
        #endregion

        public const float GATLIN_BULLET_SPEED = 20f;
        public const float GATLIN_DAMAGE_MULTIPLIER = 0.03f;
        public const float CANNON_MISSILE_SPEED = 20f;
        public const float CANNON_MISSILE_DAMAGE_MULTIPLIER = 1;
        public const float CANNON_MISSILE_EXPLODE_RADIUS = 120f;
        public const float LASER_DAMAGE_MULTIPLIER = 1;
        public const int SUMMON_MIN_COLUMN = 5;
        public const float SMASH_RANGE = 200f;
        public const float SMASH_DAMAGE_MULTIPLIER = 18f;

        public const float DRILL_DAMAGE_MULTIPLIER = 18f;
        public static readonly Vector3 GATLIN_PROJECTILE_OFFSET = new Vector3(70, 35, 0);
        public static readonly Vector3 CANNON_MISSILE_OFFSET = new Vector3(70, 27, 0);
        public static readonly Vector3 LASER_OFFSET = new Vector3(70, 27, 0);
        public static readonly Vector3 SUMMON_OFFSET = new Vector3(40, 0, 0);
        public static readonly Vector3 SMASH_OFFSET = new Vector3(0, 0, 0);
        private static readonly EntityStateMachine stateMachine = new KrakenTentacleStateMachine();
        private static readonly KrakenTentaclePredicator krakenTentaclePredicator = new KrakenTentaclePredicator();
        private static readonly KrakenPredicator krakenPredicator = new KrakenPredicator();
        private static readonly KrakenTentacleDetector gatlinDetector = new KrakenTentacleDetector(4, GATLIN_PROJECTILE_OFFSET);
        private static readonly KrakenTentacleDetector cannonDetector = new KrakenTentacleDetector(24, CANNON_MISSILE_OFFSET);
        private static readonly KrakenTentacleDetector laserDetector = new KrakenTentacleDetector(24, LASER_OFFSET);
        private static readonly KrakenTentacleDetector smashDetector = new KrakenTentacleDetector(40, SMASH_OFFSET, SMASH_RANGE)
        {
            canDetectInvisible = true
        };
        private static readonly CollisionDetector drillDetector = new CollisionDetector(true)
        {
            mask = EntityCollisionHelper.MASK_ENEMY | EntityCollisionHelper.MASK_BOSS
        };
        public class KrakenTentaclePredicator : IPredicator<Entity>
        {
            public void SetTile(int column, int lane)
            {
                this.column = column;
                this.lane = lane;
            }
            public bool IsMatch(Entity value)
            {
                return value.IsEntityOf(VanillaBossID.krakenTentacle) && value.GetColumn() == column && value.GetLane() == lane;
            }
            private int column;
            private int lane;
        }
        public class KrakenPredicator : IPredicator<Entity>
        {
            public void SetTile(int column, int lane)
            {
                this.column = column;
                this.lane = lane;
            }
            public bool IsMatch(Entity value)
            {
                if (!value.IsEntityOf(VanillaBossID.kraken))
                    return false;
                if (value.IsCollisionCheckDisabled())
                    return false;
                var rect = value.GetOverlappedTileRect();
                return column >= rect.min.x && column <= rect.max.x && lane >= rect.min.y && lane <= rect.max.y;
            }
            private int column;
            private int lane;
        }
        public class KrakenTentacleDetector : Detector
        {
            public KrakenTentacleDetector(float bulletSize, Vector3 offset, float maxRange = 80000)
            {
                this.bulletSize = bulletSize;
                this.offset = offset;
                this.maxRange = maxRange;
            }

            protected override Bounds GetDetectionBounds(Entity self)
            {
                return GetDetectionBoundsAtPosition(self, self.Position);
            }
            public Bounds GetDetectionBoundsAtTile(Entity entity, int column, int lane)
            {
                var pos = entity.Level.GetEntityGridPosition(column, lane);
                return GetDetectionBoundsAtPosition(entity, pos);
            }
            public Bounds GetDetectionBoundsAtPosition(Entity entity, Vector3 position)
            {
                var sizeX = maxRange;
                var sizeY = bulletSize;
                var sizeZ = bulletSize;
                var centerX = position.x + entity.GetFacingX() * (sizeX * 0.5f + offset.x);
                var centerY = position.y + sizeY * 0.5f + offset.y;
                var centerZ = position.z + sizeZ * 0.5f + offset.z;
                return new Bounds(new Vector3(centerX, centerY, centerZ), new Vector3(sizeX, sizeY, sizeZ));
            }
            public float bulletSize = 4;
            public Vector3 offset;
            public float maxRange = 80000;
        }
    }
}